using System;using System.Data;using System.Data.Common;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows.Forms;
class CommonCodeValueRegression{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;static Assembly app;static Type repo,dialogType;static List<long> ids=new List<long>();static int checks;static string name="CC_FEE_TEST_"+Guid.NewGuid().ToString("N");
 static object Field(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Get(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static void Set(object o,string n,object v){o.GetType().GetProperty(n,F).SetValue(o,v,null);}static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}static object Repo(string n,params object[] args){foreach(var m in repo.GetMethods())if(m.Name==n&&m.GetParameters().Length==args.Length){try{return m.Invoke(null,args);}catch(TargetInvocationException e){throw e.InnerException;}}throw new Exception(n);}
 static async Task Wait(Func<bool> ready){var watch=Stopwatch.StartNew();while(!ready()){if(watch.Elapsed.TotalSeconds>30)throw new TimeoutException();await Task.Delay(20);}}
 static Form New(object arg){var f=(Form)Activator.CreateInstance(dialogType,new object[]{arg});f.StartPosition=FormStartPosition.Manual;f.Left=f.Top=-4000;f.ShowInTaskbar=false;return f;}
 static async Task Save(Form d){((IButtonControl)Field(d,"btnOK")).PerformClick();await Wait(()=> d.IsDisposed || d.DialogResult==DialogResult.OK);Check(d.DialogResult==DialogResult.OK,"UI save completes");}
 static async Task Run(Form host){using(var d=New("배송방법")){d.Show(host);Check((bool)Get(Field(d,"labelItemValue"),"Visible")&&(bool)Get(Field(d,"tbItemValue"),"Visible"),"Shipping shows amount controls");Check(!(bool)Get(Field(d,"tbItemValue"),"ReadOnly"),"Amount is editable");Set(Field(d,"tbItemName"),"Text",name);Set(Field(d,"tbItemValue"),"Text","3,500");await Save(d);ids.Add((long)Get(d,"SavedSeqNo"));}
 long id=ids[0];Check(Convert.ToString(((DataRow)Repo("GetCommonCode",id))["ItemValue"])=="3500","Shipping amount saved to ItemValue");using(var d=New(id)){d.Show(host);await Wait(()=> (bool)Get(Field(d,"btnOK"),"Enabled"));Check((bool)Get(Field(d,"labelItemValue"),"Visible")&&(string)Get(Field(d,"tbItemValue"),"Text")=="3500","Edit restores amount and visibility");Set(Field(d,"tbItemValue"),"Text","4500");await Save(d);}Check(Convert.ToString(((DataRow)Repo("GetCommonCode",id))["ItemValue"])=="4500","Edit writes updated amount");
 Repo("SaveItem",(long?)id,"배송방법",name);Check(Convert.ToString(((DataRow)Repo("GetCommonCode",id))["ItemValue"])=="4500","Legacy three-argument save preserves amount");
 using(var d=New(id)){d.Show(host);await Wait(()=> (bool)Get(Field(d,"btnOK"),"Enabled"));Set(Field(d,"tbItemValue"),"Text","");await Save(d);}Check(((DataRow)Repo("GetCommonCode",id))["ItemValue"]==DBNull.Value,"Blank amount saved as NULL");
 long other=(long)Repo("SaveItem",null,"CC_OTHER_TEST",name,"9999");ids.Add(other);Check(((DataRow)Repo("GetCommonCode",other))["ItemValue"]==DBNull.Value,"Non-shipping save ignores amount");using(var c=(DbConnection)app.GetType("PineTree.Classes.DB").GetMethod("CreateConnection").Invoke(null,null)){c.Open();using(var q=c.CreateCommand()){q.CommandText="UPDATE CommonCode SET ItemValue='KEEP' WHERE SeqNo=@Id";var p=q.CreateParameter();p.ParameterName="@Id";p.Value=other;q.Parameters.Add(p);q.ExecuteNonQuery();}}
 using(var d=New(other)){d.Show(host);await Wait(()=> (bool)Get(Field(d,"btnOK"),"Enabled"));Check(!(bool)Get(Field(d,"labelItemValue"),"Visible")&&!(bool)Get(Field(d,"tbItemValue"),"Visible"),"Other group hides amount controls");Set(Field(d,"tbItemValue"),"Text","9999");await Save(d);}Check(Convert.ToString(((DataRow)Repo("GetCommonCode",other))["ItemValue"])=="KEEP","Other group's existing ItemValue preserved");
 foreach(var value in new[]{"-1","abc","999999999999999999999999999999999"}){bool bad=false;try{Repo("NormalizeDeliveryItemValue",value);}catch(ArgumentException){bad=true;}Check(bad,"Invalid amount rejected");}Check((string)Repo("NormalizeDeliveryItemValue","0")=="0","Zero fee accepted");Console.WriteLine("PASS: "+checks+" common-code value checks");}
 [STAThread]static int Main(string[]args){int exit=0;try{Application.EnableVisualStyles();app=Assembly.LoadFrom(Path.GetFullPath(args[0]));repo=app.GetType("PineTree.Classes.CommonCodeRepository");dialogType=app.GetType("PineTree.Dialogs.DialogCommonCode");using(var host=new Form{ShowInTaskbar=false,StartPosition=FormStartPosition.Manual,Left=-4000,Top=-4000}){host.Shown+=async delegate{try{await Run(host);}catch(Exception e){Console.Error.WriteLine(e);exit=1;}finally{host.Close();}};Application.Run(host);}}catch(Exception e){Console.Error.WriteLine(e);exit=1;}finally{if(ids.Count>0)Repo("DeleteItems",ids);Console.WriteLine("Cleaned temporary common-code fixtures");}return exit;}
}
